import {execFileSync} from 'node:child_process';
import {mkdtempSync,mkdirSync,writeFileSync,readFileSync,rmSync,chmodSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join,dirname} from 'node:path';
import {createHash} from 'node:crypto';
import {preflightDelivery} from '/Users/silencehan/Projects/NewChanlun-1456-sandcastle/.sandcastle/delivery-bundle.ts';
const hash=s=>createHash('sha256').update(s).digest('hex');
const root=mkdtempSync(join(tmpdir(),'1456-more-'));
function make(name,submod=false){
 const repo=join(root,name);mkdirSync(repo);
 const run=(r,...args)=>execFileSync('git',['-C',r,...args],{encoding:'utf8',stdio:['ignore','pipe','pipe']}).trim();
 const git=(...args)=>run(repo,...args);
 const init=r=>{run(r,'init','-q');run(r,'config','user.name','Fixture');run(r,'config','user.email','fixture@example.invalid');};
 const write=(p,s)=>{mkdirSync(dirname(join(repo,p)),{recursive:true});writeFileSync(join(repo,p),s)};
 const commit=()=>{git('add','.');git('-c','commit.gpgsign=false','commit','-qm','fixture');return git('rev-parse','HEAD')};
 init(repo);git('config','core.filemode','true');write('app.js','module.exports=1;\n');write('helper.js','module.exports=1;\n');
 if(submod){const inner=join(repo,'submod');mkdirSync(inner);init(inner);write('submod/a.js','module.exports=1;\n');run(inner,'add','.');run(inner,'-c','commit.gpgsign=false','commit','-qm','submodule initial');}
 const base=commit();write('app.js','module.exports=2;\n');
 if(submod){const inner=join(repo,'submod');write('submod/a.js','module.exports=2;\n');run(inner,'add','.');run(inner,'-c','commit.gpgsign=false','commit','-qm','submodule updated');}
 write('.chanlun/review-results/issue1456/evidence.md','Evidence for fixture.\n');const head=commit();
 const artifact={path:'.chanlun/review-results/issue1456/evidence.md',sha256:hash(readFileSync(join(repo,'.chanlun/review-results/issue1456/evidence.md')))};
 const changes=[{path:'app.js',beforeSha256:hash('module.exports=1;\n'),afterSha256:hash('module.exports=2;\n'),beforeMode:'100644',afterMode:'100644'}];
 const manifest={schemaVersion:1,ticket:1456,base,head,productDiff:changes,requiredReports:[artifact.path],reports:[artifact],reviews:[{report:artifact,covers:changes}],requiredChecks:['syntax'],checks:[{id:'syntax',kind:'compile',status:'passed',evidence:artifact,covers:changes,command:'node --check app.js',executedAt:new Date().toISOString(),exitCode:0}],scan:{status:'passed',scannedHead:head,evidence:artifact,executedAt:new Date().toISOString(),exitCode:0}};
 return {repo,git,write,commit,manifest};
}
const verify=(name,f)=>{const r=preflightDelivery(f.repo,f.manifest);console.log(JSON.stringify({case:name,status:r.status,codes:r.diagnostics.map(d=>d.code)}));return r.status;};
try {
 const clean=make('clean');verify('clean_control',clean);
 const hidden=make('hidden');hidden.git('update-index','--assume-unchanged','helper.js');hidden.write('helper.js','module.exports=999;\n');verify('hidden_unchanged_product',hidden);
 const mode=make('mode');chmodSync(join(mode.repo,'helper.js'),0o755);mode.git('config','core.filemode','false');verify('hidden_executable_bit',mode);
 const sub=make('submodule',true);sub.git('config','diff.ignoreSubmodules','all');verify('hidden_committed_submodule',sub);
 const replace=make('replacement');const benign=replace.manifest.head;replace.write('hidden.js','module.exports="unreviewed product";\n');const rawHead=replace.commit();replace.git('replace',rawHead,benign);replace.git('read-tree','--reset','-u',benign);replace.manifest.head=rawHead;replace.manifest.scan.scannedHead=rawHead;verify('replacement_hides_product',replace);
} finally {rmSync(root,{recursive:true,force:true});}
